/**
 * An account session (`ov_core::api::Account`).
 */
public protocol AccountProtocol: AnyObject, Sendable {
    
    /**
     * Accepts an invitation.
     */
    func acceptInvitation(token: Data, cancel: CancelToken) async throws  -> Member
    
    /**
     * Whether In-App Purchase is available.
     */
    func appleEligibility(orgId: String?, cancel: CancelToken) async throws  -> AppleEligibility
    
    /**
     * A page of the audit log.
     */
    func auditLog(orgId: String, before: String?, limit: UInt32?, cancel: CancelToken) async throws  -> AuditPage
    
    /**
     * Cancels an invitation.
     */
    func cancelInvitation(orgId: String, invitationId: String, cancel: CancelToken) async throws 
    
    /**
     * Changes the email with the code.
     */
    func changeEmail(email: String, code: String, password: Data, cancel: CancelToken) async throws 
    
    /**
     * Changes the password; returns the new AUK.
     */
    func changePassword(current: Data, next: Data, kdf: KdfOverrides?, cancel: CancelToken) async throws  -> Data
    
    /**
     * Changes a member's role.
     */
    func changeRole(vaultId: String, principal: String, role: VaultRole, cancel: CancelToken) async throws 
    
    /**
     * Confirms a member (granting vaults).
     */
    func confirmMember(orgId: String, member: Member, vaults: [VaultGrantRequest], cancel: CancelToken) async throws  -> Member
    
    /**
     * Confirms two-step verification with a code.
     */
    func confirmTwoStep(code: String, cancel: CancelToken) async throws 
    
    /**
     * Creates an organization.
     */
    func createOrg(name: String, cancel: CancelToken) async throws  -> Org
    
    /**
     * Creates a service account.
     */
    func createServiceAccount(orgId: String, input: NewServiceAccount, cancel: CancelToken) async throws  -> CreatedServiceAccount
    
    /**
     * Creates a share link.
     */
    func createShare(payload: SharePayload, options: ShareOptions, cancel: CancelToken) async throws  -> CreatedShare
    
    /**
     * Schedules deletion; returns when it happens.
     */
    func deleteAccount(password: Data, confirm: String, cancel: CancelToken) async throws  -> String
    
    /**
     * Deletes an organization.
     */
    func deleteOrg(orgId: String, cancel: CancelToken) async throws 
    
    /**
     * Deletes a service account.
     */
    func deleteServiceAccount(saId: String, cancel: CancelToken) async throws 
    
    /**
     * What deleting the account would do.
     */
    func deletionPreview(cancel: CancelToken) async throws  -> DeletionPreview
    
    /**
     * The signed-in devices.
     */
    func devices(cancel: CancelToken) async throws  -> [Device]
    
    /**
     * Disables two-step verification.
     */
    func disableTwoStep(code: String, cancel: CancelToken) async throws 
    
    /**
     * An organization's open invitations.
     */
    func invitations(orgId: String, cancel: CancelToken) async throws  -> [Invitation]
    
    /**
     * Invites someone.
     */
    func invite(orgId: String, email: String, role: OrgRole, cancel: CancelToken) async throws  -> Invitation
    
    /**
     * Issues a new secret for a service account.
     */
    func issueServiceAccountSecret(saId: String, name: String?, expiresAt: String?, cancel: CancelToken) async throws  -> IssuedSecret
    
    /**
     * The account's share links.
     */
    func listShares(cancel: CancelToken) async throws  -> [ShareListing]
    
    /**
     * Looks a user up by email.
     */
    func lookUp(email: String, cancel: CancelToken) async throws  -> ShareRecipient
    
    /**
     * The organization vaults this account manages.
     */
    func managedOrgVaults(orgId: String, cancel: CancelToken) async throws  -> [VaultInfo]
    
    /**
     * The profile.
     */
    func me(cancel: CancelToken) async throws  -> Profile
    
    /**
     * The members of a vault.
     */
    func members(vaultId: String, cancel: CancelToken) async throws  -> [VaultMember]
    
    /**
     * One organization.
     */
    func org(orgId: String, cancel: CancelToken) async throws  -> Org
    
    /**
     * An organization's members.
     */
    func orgMembers(orgId: String, cancel: CancelToken) async throws  -> [Member]
    
    /**
     * The organizations this account belongs to.
     */
    func orgs(cancel: CancelToken) async throws  -> [OrgMembership]
    
    /**
     * The account's plan.
     */
    func plan(cancel: CancelToken) async throws  -> Plan?
    
    /**
     * A share recipient by principal.
     */
    func recipient(principal: String, display: String?, cancel: CancelToken) async throws  -> ShareRecipient
    
    /**
     * Resets the account with a recovery link.
     */
    func recover(token: Data, password: Data, kdf: KdfOverrides?, trustDevice: Bool, cancel: CancelToken) async throws  -> NewAccount
    
    /**
     * What a recovery reset link will do.
     */
    func recoverInfo(token: Data, cancel: CancelToken) async throws  -> RecoveryReset
    
    /**
