#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAccount: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Account

    public static func lift(_ handle: UInt64) throws -> Account {
        return Account(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Account) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Account {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Account, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccount_lift(_ handle: UInt64) throws -> Account {
    return try FfiConverterTypeAccount.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAccount_lower(_ value: Account) -> UInt64 {
    return FfiConverterTypeAccount.lower(value)
}






/**
 * The offline cache (SPEC §20), per user and vault; see `ov_core::host::BlobCache`.
 */
public protocol BlobCache: AnyObject, Sendable {
    
    /**
     * The cached vault, or `nil`.
     */
    func load(userId: String, vaultId: String) async throws  -> CachedVault?
    
    /**
     * Stores the cached vault, replacing the old record.
     */
    func save(userId: String, vaultId: String, v: CachedVault) async throws 
    
    /**
     * Removes one vault's record.
     */
    func remove(userId: String, vaultId: String) async throws 
    
    /**
     * The ids of every vault cached for `user_id`.
     */
    func list(userId: String) async throws  -> [String]
    
    /**
     * A per-user (or, with `user_id == ""`, per-device) record.
     */
    func loadMeta(userId: String, name: String) async throws  -> Data?
    
    /**
     * Stores a per-user record.
     */
    func saveMeta(userId: String, name: String, value: Data) async throws 
    
    /**
     * Removes everything cached for `user_id`.
     */
    func clearUser(userId: String) async throws 
    
}
/**
 * The offline cache (SPEC §20), per user and vault; see `ov_core::host::BlobCache`.
 */
open class BlobCacheImpl: BlobCache, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_ov_ffi_fn_clone_blobcache(self.handle, $0) }
