#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlobCache: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<BlobCache>()

    typealias FfiType = UInt64
    typealias SwiftType = BlobCache

    public static func lift(_ handle: UInt64) throws -> BlobCache {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return BlobCacheImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: BlobCache) -> UInt64 {
         if let rustImpl = value as? BlobCacheImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlobCache {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: BlobCache, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlobCache_lift(_ handle: UInt64) throws -> BlobCache {
    return try FfiConverterTypeBlobCache.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeBlobCache_lower(_ value: BlobCache) -> UInt64 {
    return FfiConverterTypeBlobCache.lower(value)
}






/**
 * The body of an open stream, read chunk by chunk.
 */
public protocol ByteStream: AnyObject, Sendable {
    
    /**
     * The response status the stream was opened with.
     */
    func status()  -> UInt16
    
    /**
     * The next chunk, or `nil` when the server closed the stream.
     */
    func nextChunk() async throws  -> Data?
    
    /**
     * Closes the stream; later `next_chunk` calls return `nil`.
     */
    func close() 
    
}
