/**
 * The entry point: a configuration plus the Host (`ov_core::api::OvClient`).
 */
public protocol OvClientProtocol: AnyObject, Sendable {
    
    /**
     * The configuration.
     */
    func config() throws  -> ClientConfig
    
    /**
     * An `Account` for `issuer`, restoring a stored session if there is one.
     */
    func connect(issuer: String, cancel: CancelToken) async throws  -> Account
    
    /**
     * Creates a new local database on this client's Host clock (contract-v1.6).
     */
    func createLocal(name: String, credentials: KdbxCredentials, cancel: CancelToken) async throws  -> Vault
    
    /**
     * Fetches the server's discovery document (SPEC §1).
     */
    func discover(issuer: String, cancel: CancelToken) async throws  -> ServerConfig
    
    /**
     * Forgets a remembered account.
     */
    func forgetRemembered(issuer: String, userId: String) async throws 
    
    /**
     * Whether any vault of `user_id` has edits not yet uploaded.
     */
    func hasPendingEdits(userId: String) async throws  -> Bool
    
    /**
     * Marks a remembered account as checked now.
     */
    func markRememberedChecked(issuer: String, userId: String) async throws 
    
    /**
     * Opens a local `.kdbx` on this client's Host clock (contract-v1.6).
     */
    func openLocal(kdbx: Data, credentials: KdbxCredentials, cancel: CancelToken) async throws  -> Vault
    
    /**
     * Opens a share link (SPEC §22).
     */
    func openShare(api: String, link: Data, passcode: Data?, info: ShareInfo?, cancel: CancelToken) async throws  -> OpenedShare
    
    /**
     * Remembers an account.
     */
    func rememberAccount(email: String, issuer: String, userId: String) async throws 
    
    /**
     * The remembered accounts (SPEC §21).
     */
    func rememberedAccounts() async throws  -> [RememberedAccount]
    
    /**
     * The session state of a remembered account.
     */
    func sessionState(issuer: String, userId: String) async throws  -> SessionState
    
    /**
     * Records a scheduled deletion on a remembered account.
     */
    func setRememberedDeletion(issuer: String, userId: String, at: String?) async throws 
    
    /**
     * Public facts about a share link (SPEC §22).
     */
    func shareInfo(api: String, shareId: String, cancel: CancelToken) async throws  -> ShareInfo
    
}
