/**
 * Secrets that persist (for example the Keychain on Apple platforms). Keys are chosen by the core; see
 * `ov_core::host::SecureStore`.
 */
public protocol SecureStore: AnyObject, Sendable {
    
    /**
     * The value for `key`, or `nil`. An unreadable store throws (not the same as `nil`).
     */
    func get(key: String) async throws  -> Data?
    
    /**
     * Stores `value` under `key`, replacing any old value. The host wipes `value` after use.
     */
    func set(key: String, value: Data) async throws 
    
    /**
     * Removes `key`; a missing key is not an error.
     */
    func delete(key: String) async throws 
    
}
