     */
    func deleteEntry(entryId: String) throws 
    
    /**
     * Deletes a group.
     */
    func deleteGroup(groupId: String) throws 
    
    /**
     * Edits an entry.
     */
    func editEntry(entryId: String, input: EntryInput) throws 
    
    /**
     * Empties the Recycle Bin.
     */
    func emptyRecycleBin() throws 
    
    /**
     * The group at a path, creating missing groups.
     */
    func ensureGroup(path: String) throws  -> String
    
    /**
     * Every entry.
     */
    func entries(includeRecycleBin: Bool) throws  -> [EntrySummary]
    
    /**
