     */
    func exportKdbxWith(credentials: KdbxCredentials, groupIds: [String]?, kdf: KdbxKdf, cancel: CancelToken) async throws  -> Data
    
    /**
     * Exports as plain CSV or JSON (secret: the caller wipes it).
     */
    func exportPlain(format: ExportFormat, groupIds: [String]?) throws  -> Data
    
    /**
     * The entry a reference names.
     */
    func find(reference: String) throws  -> EntryRecord
    
    /**
     * The group at a `/`-separated path.
     */
    func groupIdAt(path: String) throws  -> String?
    
    /**
     * Every group.
     */
    func groups() throws  -> [GroupInfo]
    
    /**
     * Whether there are edits not yet uploaded.
     */
    func hasPendingEdits() async throws  -> Bool
    
    /**
     * An entry's history.
     */
    func history(entryId: String) throws  -> [EntryRecord]
    
    /**
     * The vault id.
     */
    func id() throws  -> String
    
    /**
     * Imports another open vault into this one (contract-v1.6).
     */
    func importFrom(source: Vault, mode: LocalImportMode) throws  -> ImportSummary
    
    /**
     * What importing this vault would bring in (contract-v1.6).
     */
    func importPreview() throws  -> ImportPreview
    
    /**
     * The groups an import can go into (contract-v1.6).
     */
    func importTargets() throws  -> [ImportTarget]
    
    /**
     * The server's record (account vaults).
     */
    func info() throws  -> VaultInfo?
    
    /**
     * Whether an entry or group is in the Recycle Bin.
     */
    func isInRecycleBin(id: String) throws  -> Bool
    
    /**
     * Whether the vault came from the offline cache.
     */
    func isOffline() throws  -> Bool
    
    /**
     * Whether edits are refused.
     */
    func isReadOnly() throws  -> Bool
    
    /**
     * Saves local edits to the offline cache.
     */
    func keepEdits() async throws 
    
    /**
     * A database custom data value (contract-v1.6).
     */
    func metaCustomData(key: String) throws  -> String?
    
    /**
     * Moves an entry.
     */
    func moveEntry(entryId: String, groupId: String) throws 
    
    /**
     * Moves a group.
     */
    func moveGroup(groupId: String, parentId: String) throws 
    
    /**
     * The display name.
     */
    func name() throws  -> String
    
    /**
     * The field a reference names.
     */
    func readField(reference: String) throws  -> Data
    
    /**
     * Removes an attachment.
     */
    func removeAttachment(entryId: String, name: String) throws 
    
    /**
     * Renames a group.
     */
    func renameGroup(groupId: String, name: String) throws 
    
    /**
     * Restores an entry from an older version.
     */
    func restoreEntry(version: Vault, entryId: String, groupPath: String) throws 
    
    /**
     * Restores an entry or group from the Recycle Bin.
     */
    func restoreFromRecycleBin(id: String) throws 
    
    /**
     * The root group id.
     */
    func rootGroupId() throws  -> String
    
    /**
     * Serializes a local database.
     */
    func saveLocal(cancel: CancelToken) async throws  -> Data
    
    /**
     * Adds or replaces an attachment.
     */
    func setAttachment(entryId: String, name: String, data: Data) throws 
    
    /**
     * Adds or replaces an attachment with its protected flag (`nil` keeps the replaced one's;
     * contract-v1.6).
     */
    func setAttachmentWith(entryId: String, name: String, data: Data, protected: Bool?) throws 
    
    /**
     * Sets several fields of one entry.
     */
    func setFields(reference: String, fields: [FieldInput], create: CreateMode) throws  -> SetFieldsResult
    
    /**
     * Sets a group's icon.
     */
    func setGroupIcon(groupId: String, iconId: UInt32) throws 
    
    /**
     * Sets a local database's key derivation (contract-v1.6).
     */
    func setKdf(kdf: KdbxKdf) throws 
    
    /**
     * Sets or removes a database custom data item (contract-v1.6).
     */
    func setMetaCustomData(key: String, value: String?) throws 
    
    /**
     * Renames a local database (contract-v1.6).
     */
    func setName(name: String) throws 
    
    /**
     * Syncs with the server (SPEC §10).
     */
    func sync(options: SyncOptions, cancel: CancelToken) async throws  -> SyncReport
    
    /**
     * How an entry differs in an older version.
     */
