/**
 * The AAD strings of SPEC §4-§7, §22 (`Envelope.AAD` in Swift).
 */

public enum AadKind: Equatable, Hashable {
    
    /**
     * `ov-keyset-v1` (the id is ignored).
     */
    case keyset
    /**
     * `ov-vault-key|<vault>`.
     */
    case vaultKey
    /**
     * `ov-vault-name|<vault>`.
     */
    case vaultName
    /**
     * `ov-sa-master-v1|<sa>`.
     */
    case saMaster
    /**
     * `ov-share-v1|<share>`.
     */
    case share
    /**
     * `ov-share-ref|<share>`.
     */
    case shareRef





}

#if compiler(>=6)
extension AadKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAadKind: FfiConverterRustBuffer {
    typealias SwiftType = AadKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AadKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .keyset
        
        case 2: return .vaultKey
        
        case 3: return .vaultName
        
        case 4: return .saMaster
        
