/**
 * Why a host HTTP request didn't produce a response (`ov_core::host::TransportError`).
 */
public 
enum TransportError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * No network, DNS failure or connection refused.
     */
    case Offline
    /**
     * The request timed out.
     */
    case Timeout
    /**
     * TLS failed; the text is for logs.
     */
    case Tls(
        /**
         * Detail for logs.
         */message: String
    )
    /**
     * The platform cancelled the request.
     */
    case Cancelled
    /**
     * Anything else; the text is for logs.
     */
    case Other(
        /**
         * Detail for logs.
         */message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension TransportError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTransportError: FfiConverterRustBuffer {
    typealias SwiftType = TransportError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TransportError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Offline
        case 2: return .Timeout
        case 3: return .Tls(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Cancelled
        case 5: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: TransportError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Offline:
            writeInt(&buf, Int32(1))
        
        
        case .Timeout:
            writeInt(&buf, Int32(2))
        
        
        case let .Tls(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(4))
        
        
        case let .Other(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeTransportError_lift(_ buf: RustBuffer) throws -> TransportError {
    return try FfiConverterTypeTransportError.lift(buf)
}

